-- Phase 5b suite authoring (plan 4.6), generated by drizzle-kit, then the
-- hand-written triggers at the end:
--
-- * suite_drafts, suite_draft_tasks and suite_draft_files: one open draft per
--   suite folder or new suite name (suite_drafts_source_uq), based on a
--   version of that very folder (suite_drafts_base_suite_fk) or on none for a
--   new suite; its tasks with their state against the base and the text
--   files the forms edit verbatim; every other file by blob, so draft rows
--   never hold file bytes and a blob a draft names is never removed. A
--   file's kind follows from its path where the loader's rule does not
--   depend on task.yaml: `verifier` exactly under verify/, `fixture` exactly
--   under fixtures/, `home_seed` exactly the two memory files. Drafts are
--   working state: discarding or saving one deletes it, its tasks and files
--   with it (ON DELETE CASCADE), and no evidence ever points at them.
-- * task_root_files: task.yaml, prompt.md and reference.json of each task
--   version exactly as read (size, hash, text), for the task diff's sizes
--   and hashes and for drafts that start from the bytes on disk. A table of
--   its own, immutable like tasks, so no tasks row is rewritten and every
--   reader of tasks is unchanged; versions loaded before Phase 5b have none.
-- * Deleting a skill or document (Phase 5 section 6.1) is refused while any
--   configuration version names it: configuration_versions holds their ids
--   in text[] columns, which no foreign key covers, so an AFTER DELETE
--   trigger raises the foreign_key_violation a key would, and the reference
--   trigger of 0001 now locks what it references FOR KEY SHARE, as a key
--   does, so a delete and a new configuration version cannot both commit.

CREATE TABLE "task_root_files" (
	"task_id" text NOT NULL,
	"path" text NOT NULL,
	"sha256" text NOT NULL,
	"size" bigint NOT NULL,
	"text" text,
	CONSTRAINT "task_root_files_pk" PRIMARY KEY("task_id","path"),
	CONSTRAINT "task_root_files_path_ck" CHECK ("task_root_files"."path" in ('task.yaml', 'prompt.md', 'reference.json')),
	CONSTRAINT "task_root_files_sha256_ck" CHECK ("task_root_files"."sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "task_root_files_size_ck" CHECK ("task_root_files"."size" >= 0)
);
--> statement-breakpoint
CREATE TABLE "suite_draft_files" (
	"draft_task_id" text NOT NULL,
	"path" text NOT NULL,
	"kind" text NOT NULL,
	"sha256" text NOT NULL,
	"size" bigint NOT NULL,
	CONSTRAINT "suite_draft_files_pk" PRIMARY KEY("draft_task_id","path"),
	CONSTRAINT "suite_draft_files_kind_ck" CHECK ("suite_draft_files"."kind" in ('fixture', 'expected', 'expected_home', 'home_seed', 'verifier', 'other')),
	CONSTRAINT "suite_draft_files_path_ck" CHECK ("suite_draft_files"."path" <> '' and "suite_draft_files"."path" !~ '(^/|(^|/)\.\.(/|$))'),
	CONSTRAINT "suite_draft_files_sha256_ck" CHECK ("suite_draft_files"."sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "suite_draft_files_size_ck" CHECK ("suite_draft_files"."size" >= 0),
	CONSTRAINT "suite_draft_files_verifier_ck" CHECK (("suite_draft_files"."kind" = 'verifier') = ("suite_draft_files"."path" like 'verify/%')),
	CONSTRAINT "suite_draft_files_fixture_ck" CHECK (("suite_draft_files"."kind" = 'fixture') = ("suite_draft_files"."path" like 'fixtures/%')),
	CONSTRAINT "suite_draft_files_home_seed_ck" CHECK (("suite_draft_files"."kind" = 'home_seed') = ("suite_draft_files"."path" in ('home/memories/MEMORY.md', 'home/memories/USER.md')))
);
--> statement-breakpoint
