-- Root files never change once loaded, like the task they belong to (0001).
CREATE TRIGGER task_root_files_immutable BEFORE UPDATE OR DELETE ON task_root_files
  FOR EACH ROW EXECUTE FUNCTION hermes_reject_change();
--> statement-breakpoint

-- A configuration version's resource ids must exist (0001), now holding a key
-- share lock on each skill and document it names until it commits, so a
-- concurrent delete waits for it and then sees the reference.
CREATE OR REPLACE FUNCTION hermes_configuration_versions_refs() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM 1 FROM skills WHERE skills.id = ANY(NEW.skill_ids) FOR KEY SHARE;
  PERFORM 1 FROM documents WHERE documents.id = ANY(NEW.document_ids) FOR KEY SHARE;
  IF EXISTS (SELECT 1 FROM unnest(NEW.skill_ids) AS r(id)
             WHERE r.id IS NULL OR NOT EXISTS (SELECT 1 FROM skills WHERE skills.id = r.id))
     OR EXISTS (SELECT 1 FROM unnest(NEW.document_ids) AS r(id)
             WHERE r.id IS NULL OR NOT EXISTS (SELECT 1 FROM documents WHERE documents.id = r.id))
     OR EXISTS (SELECT 1 FROM unnest(NEW.mcp_server_version_ids) AS r(id)
             WHERE r.id IS NULL OR NOT EXISTS (SELECT 1 FROM mcp_server_versions m WHERE m.id = r.id)) THEN
    RAISE EXCEPTION 'configuration version % references a skill, document or MCP definition that does not exist',
      NEW.id USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF (SELECT count(*) <> count(DISTINCT m.mcp_server_id)
      FROM mcp_server_versions m WHERE m.id = ANY(NEW.mcp_server_version_ids)) THEN
    RAISE EXCEPTION 'configuration version % uses two versions of the same MCP server', NEW.id
      USING ERRCODE = 'restrict_violation';
  END IF;
  UPDATE mcp_server_versions SET frozen_at = now()
    WHERE id = ANY(NEW.mcp_server_version_ids) AND frozen_at IS NULL;
  RETURN NEW;
END;
$$;
--> statement-breakpoint

-- Only a skill or document no configuration version names can be deleted.
-- AFTER the row is gone (and its lock taken, which waits for a version that
-- holds a key share on it), so the check sees every committed reference.
CREATE FUNCTION hermes_resource_delete_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (TG_TABLE_NAME = 'skills'
      AND EXISTS (SELECT 1 FROM configuration_versions WHERE OLD.id = ANY(skill_ids)))
     OR (TG_TABLE_NAME = 'documents'
      AND EXISTS (SELECT 1 FROM configuration_versions WHERE OLD.id = ANY(document_ids))) THEN
    RAISE EXCEPTION '% % is used by a configuration version and cannot be deleted', TG_TABLE_NAME, OLD.id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NULL;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER skills_delete_guard AFTER DELETE ON skills
  FOR EACH ROW EXECUTE FUNCTION hermes_resource_delete_guard();
--> statement-breakpoint
CREATE TRIGGER documents_delete_guard AFTER DELETE ON documents
  FOR EACH ROW EXECUTE FUNCTION hermes_resource_delete_guard();
